    },
    // endregion Calendar
    // region Filter
    async applyFilter() {
      this.eventSnapshot?.()
      await filterScheduling(this.filter)
      this.filterDialog = false
    },
    resetFilter() {
      changeLoading(true)
      this.filter = {
        user: null as any,
        status: null as any,
        payment: null as any,
        courts: 'Todos'
      }
      this.eventSnapshot = allSchedulingReactive([moment().format('YYYY-MM-DD')])
      this.filterDialog = false
      changeLoading(false)
    },
    // endregion Filter
